import{_ as e,k as i,l as t,C as l,a6 as n,A as h,j as o}from"./chunks/framework.W_BvR9CP.js";const u=JSON.parse('{"title":"\\\\\\\\protectarea","description":"The \\\\\\\\protectarea command.","frontmatter":{"title":"\\\\\\\\protectarea","page_title":"\\\\\\\\protectarea","description":"The \\\\\\\\protectarea command.","show_outline":false,"category":"WorldEdit","nav_order":3,"mentions":["stormstqr","8Crafter"]},"headers":[{"level":2,"title":"Syntax","slug":"syntax","link":"#syntax","children":[]},{"level":2,"title":"Arguments","slug":"arguments","link":"#arguments","children":[]},{"level":2,"title":"Result","slug":"result","link":"#result","children":[]},{"level":2,"title":"Examples","slug":"examples","link":"#examples","children":[]},{"level":2,"title":"History","slug":"history","link":"#history","children":[]}],"relativePath":"commands-list/--protectarea.md","filePath":"commands-list/--protectarea.md"}'),r={name:"commands-list/--protectarea.md"};function p(c,s,d,k,g,y){const a=h("CommandDetailsTable");return o(),i("div",null,[s[0]||(s[0]=t("p",null,"Sets the selected area as a protected area.",-1)),l(a,{name:"\\\\protectarea",categories:["system","world","server","worldedit"],requiredTags:["canUseChatCommands"],ultraSecurityModeSecurityLevel:"WorldEdit",version:"2.0.0",undoSupported:-1,functional:!0,deprecated:!1}),s[1]||(s[1]=n('<h2 id="syntax" tabindex="-1">Syntax <a class="header-anchor" href="#syntax" aria-label="Permalink to &quot;Syntax&quot;">​</a></h2><p><code class="shiki"><span style="--shiki-light:hsl(207, 61%, 41%);--shiki-dark:#569CD6;">\\\\protectarea</span><span style="--shiki-light:hsl(0, 0%, 47%);--shiki-dark:#878787;"> [</span><span style="--shiki-light:hsl(201, 98%, 20%);--shiki-dark:#9CDCFE;">-o</span><span style="--shiki-light:hsl(0, 0%, 47%);--shiki-dark:#878787;">]</span><span style="--shiki-light:hsl(168, 53%, 45%);--shiki-dark:#4EC9B0;"> &lt;</span><span style="--shiki-light:hsl(201, 98%, 20%);--shiki-dark:#9CDCFE;">areaType</span><span style="--shiki-light:hsl(168, 53%, 45%);--shiki-dark:#4EC9B0;">: </span><span style="--shiki-light:hsl(99, 28%, 27%);--shiki-dark:#B5CEA8;">string</span><span style="--shiki-light:hsl(168, 53%, 45%);--shiki-dark:#4EC9B0;">&gt;</span><span style="--shiki-light:hsl(168, 53%, 45%);--shiki-dark:#4EC9B0;"> &lt;</span><span style="--shiki-light:hsl(201, 98%, 20%);--shiki-dark:#9CDCFE;">name</span><span style="--shiki-light:hsl(168, 53%, 45%);--shiki-dark:#4EC9B0;">: </span><span style="--shiki-light:hsl(99, 28%, 27%);--shiki-dark:#B5CEA8;">string</span><span style="--shiki-light:hsl(168, 53%, 45%);--shiki-dark:#4EC9B0;">&gt;</span><span style="--shiki-light:hsl(0, 0%, 47%);--shiki-dark:#878787;"> [</span><span style="--shiki-light:hsl(201, 98%, 20%);--shiki-dark:#9CDCFE;">mode</span><span style="--shiki-light:hsl(0, 0%, 47%);--shiki-dark:#878787;">: (</span><span style="--shiki-light:hsl(99, 28%, 27%);--shiki-dark:#B5CEA8;">0</span><span style="--shiki-light:hsl(180, 100%, 20%);--shiki-dark:#99FFFF;">|</span><span style="--shiki-light:hsl(99, 28%, 27%);--shiki-dark:#B5CEA8;">1</span><span style="--shiki-light:hsl(0, 0%, 47%);--shiki-dark:#878787;">)</span><span style="--shiki-light:hsl(41, 53%, 33%);--shiki-dark:#D7BA7D;">[</span><span style="--shiki-light:hsl(356, 100%, 19%);--shiki-dark:#FF9DA4;">?</span><span style="--shiki-light:hsl(180, 100%, 20%);--shiki-dark:#99FFFF;">=</span><span style="--shiki-light:hsl(29, 100%, 50%);--shiki-dark:#FFC58F;">0</span><span style="--shiki-light:hsl(41, 53%, 33%);--shiki-dark:#D7BA7D;">]</span><span style="--shiki-light:hsl(0, 0%, 47%);--shiki-dark:#878787;">]</span><span style="--shiki-light:hsl(0, 0%, 47%);--shiki-dark:#878787;"> [</span><span style="--shiki-light:hsl(201, 98%, 20%);--shiki-dark:#9CDCFE;">icon_path</span><span style="--shiki-light:hsl(0, 0%, 47%);--shiki-dark:#878787;">: </span><span style="--shiki-light:hsl(99, 28%, 27%);--shiki-dark:#B5CEA8;">string</span><span style="--shiki-light:hsl(0, 0%, 47%);--shiki-dark:#878787;">]</span></code></p><indent>Adds the selection as a protected area</indent><h2 id="arguments" tabindex="-1">Arguments <a class="header-anchor" href="#arguments" aria-label="Permalink to &quot;Arguments&quot;">​</a></h2><p><code class="shiki"><span style="--shiki-light:hsl(0, 0%, 47%);--shiki-dark:#878787;">[</span><span style="--shiki-light:hsl(201, 98%, 20%);--shiki-dark:#9CDCFE;">-o</span><span style="--shiki-light:hsl(0, 0%, 47%);--shiki-dark:#878787;">]</span></code>: <a href="./../commands/commands-parameters-basics#flags-parameters">flags</a></p><indent><p>A flags parameter.</p><p>Here are what each of the flags do:</p><p><code class="shiki"><span>o</span></code>: Causes the command to overwrite the saved protected area if one exists with the same id.</p></indent><p><code class="shiki"><span style="--shiki-light:hsl(168, 53%, 45%);--shiki-dark:#4EC9B0;">&lt;</span><span style="--shiki-light:hsl(201, 98%, 20%);--shiki-dark:#9CDCFE;">areaType</span><span style="--shiki-light:hsl(168, 53%, 45%);--shiki-dark:#4EC9B0;">: </span><span style="--shiki-light:hsl(99, 28%, 27%);--shiki-dark:#B5CEA8;">string</span><span style="--shiki-light:hsl(168, 53%, 45%);--shiki-dark:#4EC9B0;">&gt;</span></code>: <a href="./../commands/parameter-types#string">string</a></p><indent><p>The category of the protected area.</p><p>For built-in categories, it should be specified like <code class="shiki"><span>noBlockBreakArea:</span></code>. The <code class="shiki"><span>:</span></code> is necessary.</p><p>For custom categories, it should NOT have a <code class="shiki"><span>:</span></code> at the end.</p></indent><p><code class="shiki"><span style="--shiki-light:hsl(168, 53%, 45%);--shiki-dark:#4EC9B0;">&lt;</span><span style="--shiki-light:hsl(201, 98%, 20%);--shiki-dark:#9CDCFE;">name</span><span style="--shiki-light:hsl(168, 53%, 45%);--shiki-dark:#4EC9B0;">: </span><span style="--shiki-light:hsl(99, 28%, 27%);--shiki-dark:#B5CEA8;">string</span><span style="--shiki-light:hsl(168, 53%, 45%);--shiki-dark:#4EC9B0;">&gt;</span></code>: <a href="./../commands/parameter-types#string">string</a></p><indent><p>The uniquie identifier of the protected area.</p></indent><p><code class="shiki"><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">[mode: 0|1(default=0)]</span></code>: <a href="./../commands/parameter-types#int">int</a></p><indent><p>The mode of the protected area.</p><p><code class="shiki"><span style="--shiki-light:#098658;--shiki-dark:#B5CEA8;">0</span></code>: The area is protected.</p><p><code class="shiki"><span style="--shiki-light:#098658;--shiki-dark:#B5CEA8;">1</span></code>: The area is excluded from protection from any other areas of the same category.</p><p>For example if there was an area with mode <code class="shiki"><span style="--shiki-light:#098658;--shiki-dark:#B5CEA8;">0</span></code> of the built-in category <code class="shiki"><span>noBlockBreakArea:</span></code> that covered <code class="shiki"><span>23 50 26</span></code> to <code class="shiki"><span>37 80 50</span></code>, then an area with mode <code class="shiki"><span style="--shiki-light:#098658;--shiki-dark:#B5CEA8;">1</span></code> of the bulit-in category <code class="shiki"><span>noBlockBreakArea:</span></code> that covered <code class="shiki"><span>28 60 29</span></code> to <code class="shiki"><span>34 70 32</span></code> would cause any block breaking in the area <code class="shiki"><span>28 60 29</span></code> to <code class="shiki"><span>34 70 32</span></code> to not be prevented.</p><p>If there was an area with mode <code class="shiki"><span style="--shiki-light:#098658;--shiki-dark:#B5CEA8;">0</span></code> of the built-in category <code class="shiki"><span>noBlockBreakArea:</span></code> that covered <code class="shiki"><span>23 50 26</span></code> to <code class="shiki"><span>37 80 50</span></code>, then an area with mode <code class="shiki"><span style="--shiki-light:#098658;--shiki-dark:#B5CEA8;">1</span></code> of the custom category <code class="shiki"><span>myCustomNoBlockBreakingAreaCategory</span></code> that covered <code class="shiki"><span>28 60 29</span></code> to <code class="shiki"><span>34 70 32</span></code> would <strong>NOT</strong> cause any block breaking in the area <code class="shiki"><span>28 60 29</span></code> to <code class="shiki"><span>34 70 32</span></code> to not be prevented.</p><p>If there was an area with mode <code class="shiki"><span style="--shiki-light:#098658;--shiki-dark:#B5CEA8;">0</span></code> of the built-in category <code class="shiki"><span>noBlockBreakArea:</span></code> that covered <code class="shiki"><span>23 50 26</span></code> to <code class="shiki"><span>37 80 50</span></code>, then an area with mode <code class="shiki"><span style="--shiki-light:#098658;--shiki-dark:#B5CEA8;">1</span></code> of the built-in category <code class="shiki"><span>protectedArea:</span></code> that covered <code class="shiki"><span>28 60 29</span></code> to <code class="shiki"><span>34 70 32</span></code> would also <strong>NOT</strong> cause any block breaking in the area <code class="shiki"><span>28 60 29</span></code> to <code class="shiki"><span>34 70 32</span></code> to not be prevented.</p><p>So for a mode <code class="shiki"><span style="--shiki-light:#098658;--shiki-dark:#B5CEA8;">1</span></code> (exclusion) area, it <strong>MUST</strong> be in the exact same category as the mode <code class="shiki"><span style="--shiki-light:#098658;--shiki-dark:#B5CEA8;">0</span></code> (protection) area that it is trying to exclude the protection from.</p><p>Mode <code class="shiki"><span style="--shiki-light:#098658;--shiki-dark:#B5CEA8;">1</span></code> areas <strong>ALWAYS</strong> have priority over mode <code class="shiki"><span style="--shiki-light:#098658;--shiki-dark:#B5CEA8;">0</span></code> areas.</p><p>Default: <code class="shiki"><span style="--shiki-light:#098658;--shiki-dark:#B5CEA8;">0</span></code></p></indent><p><code class="shiki"><span style="--shiki-light:hsl(0, 0%, 47%);--shiki-dark:#878787;">[</span><span style="--shiki-light:hsl(201, 98%, 20%);--shiki-dark:#9CDCFE;">icon_path</span><span style="--shiki-light:hsl(0, 0%, 47%);--shiki-dark:#878787;">: </span><span style="--shiki-light:hsl(99, 28%, 27%);--shiki-dark:#B5CEA8;">string</span><span style="--shiki-light:hsl(0, 0%, 47%);--shiki-dark:#878787;">]</span></code>: <a href="./../commands/parameter-types#string">string</a></p><indent><p>The icon path of the protected area.</p><p>This is used in the <a href="./../main-menu/manage-protected-areas">Manage Protected Areas</a> menu.</p><p>If left blank, the area will have no icon.</p><p>The icon path should be relative to the root folder of the resource packs.</p><p>The file extension is optional.</p><p>Examples:</p><ul><li><code class="shiki"><span>textures/blocks/stone</span></code></li><li><code class="shiki"><span>textures/ui/debug_glyph_color</span></code></li><li><code class="shiki"><span>textures/ui/debug_glyph_color.png</span></code></li><li><code class="shiki"><span>pack_icon</span></code></li><li><code class="shiki"><span>pack_icon.png</span></code></li></ul></indent><h2 id="result" tabindex="-1">Result <a class="header-anchor" href="#result" aria-label="Permalink to &quot;Result&quot;">​</a></h2><table class="wikitable" data-description="command results"><tbody><tr><th>Command</th><th>Trigger</th><th>Result</th></tr><tr><td align="center" rowspan="3"><p>Any</p></td><td> The command is incomplete, or any argument is not specified correctly. </td><td align="center" rowspan="1" class="tc-unknown"> Unparseable</td></tr><tr><td> There is already an area in the specified category with the same name and the `-o` flag was not specified. </td><td align="center" class="tc-no" colspan="2">Failed</td></tr><tr><td> The specified category does not exist. </td><td align="center" class="tc-no" colspan="2">Failed</td></tr><tr><td align="center" class="tc-yes">Otherwise</td><td align="center" class="tc-yes" colspan="2">Successful</td></tr></tbody></table><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h2><ul><li>To add the selected area as the protected area to the built-in category <code class="shiki"><span>noBlockBreakArea:</span></code>, with the name <code class="shiki"><span>myAntiBlockBreakingArea1</span></code>, and the icon path <code class="shiki"><span>textures/blocks/stone</span></code>: <ul><li><code class="shiki"><span style="--shiki-light:#AF00DB;--shiki-dark:#C586C0;">\\\\protectarea</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;"> noBlockBreakArea: </span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;">myAntiBlockBreakingArea1</span><span style="--shiki-light:#098658;--shiki-dark:#B5CEA8;"> 0</span><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;"> textures/blocks/stone</span></code></li></ul></li><li>To exclude the selected section of a <code class="shiki"><span>noBlockBreakArea:</span></code> protected area from the protection: <ul><li><code class="shiki"><span style="--shiki-light:#AF00DB;--shiki-dark:#C586C0;">\\\\protectarea</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;"> noBlockBreakArea: </span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;">myAntiBlockBreakingArea1_exclusion1</span><span style="--shiki-light:#098658;--shiki-dark:#B5CEA8;"> 1</span></code></li></ul></li><li>To addd the selected area as the protected area to the custom category <code class="shiki"><span>myCustomCategory</span></code>, with the name <code class="shiki"><span>myCustomProtectedArea1</span></code>, and the icon path <code class="shiki"><span>textures/ui/debug_glyph_color</span></code>: <ul><li><code class="shiki"><span style="--shiki-light:#AF00DB;--shiki-dark:#C586C0;">\\\\protectarea</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;"> myCustomCategory </span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;">myCustomProtectedArea1</span><span style="--shiki-light:#098658;--shiki-dark:#B5CEA8;"> 0</span><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;"> textures/ui/debug_glyph_color</span></code></li></ul></li></ul><h2 id="history" tabindex="-1">History <a class="header-anchor" href="#history" aria-label="Permalink to &quot;History&quot;">​</a></h2><table class="wikitable pixel-image bgType2" data-description="History"><tbody><tr class="collapsible collapsible-rows"><th colspan="16" style="border-bottom:none;"> Debug Sticks </th></tr><tr class="collapsible-row"><th class="nowrap" rowspan="1" colspan="1"> ? </th><th colspan="4" rowspan="1"> ? </th><td><p>Added <code class="shiki"><span style="--shiki-light:hsl(207, 61%, 41%);--shiki-dark:#569CD6;">\\\\protectarea</span></code>.</p></td></tr><tr class="collapsible-row"><th class="nowrap" rowspan="2" colspan="1"><a href="/changelogs/v1.33.0" title="Debug Sticks v1.33.0"> v1.33.0 </a></th><th colspan="4" rowspan="2"><a href="/changelogs/v1.33.0" title="Debug Sticks v1.33.0"> release </a></th><td><p>The <code class="shiki"><span>\\\\protectarea</span></code> command now supports custom protected area categories. The built-in ones are still specified exactly the same way, but for the custom ones, you just put the same id that you put when creating the category, with the custom categories, you do not include a <code class="shiki"><span>:</span></code> at the end.</p></td></tr><tr class="collapsible-row"><td><p>Added the <code class="shiki"><span>o</span></code> flag to the <code class="shiki"><span>\\\\protectarea</span></code> command. This flag causes the command to overwrite the saved protected area if one exists with the same id.</p></td></tr><tr class="collapsible collapsible-rows"><th colspan="16" style="border-bottom:none;"> Server Utilities </th></tr><tr class="collapsible-row"><th class="nowrap" rowspan="1" colspan="1"><a href="/changelogs/v1.35.0" title="Server Utilities v1.35.0"> v1.35.0 </a></th><th colspan="4" rowspan="1"><a href="/changelogs/v1.35.0-rc.1" title="Server Utilities v1.35.0-RC.1"> RC1 </a><a href="https://github.com/8Crafter-Studios/8Crafter-s-Debug-Sticks-BP-Development/commit/4da7a07768d1f5a67ff18415417e7817ab75b699" title="Debug Sticks v1.35.0-preview.20+BULID.4 (Commit 4da7a07768d1f5a67ff18415417e7817ab75b699)" class="minetip scicon"></a></th><td><p>Fixed a bug where the <code class="shiki"><span style="--shiki-light:hsl(207, 61%, 41%);--shiki-dark:#569CD6;">\\\\protectarea</span></code> command would always throw an error saying that the area category was invalid, even when it was valid.</p></td></tr></tbody></table>',20))])}const C=e(r,[["render",p]]);export{u as __pageData,C as default};
